INSERT INTO complaints (title, category, priority, description, submitted_by, submitted_by_role, submitted_date, status, response) VALUES
('Classroom projector not working in Room 103', 'Infrastructure', 'Medium', 'The projector in Room 202 has not been working for the past 9 days. It affects all lectures scheduled in that room.', 'Abhishek Dey', 'student', '2025-04-28', 'Open', NULL),
('Wi-Fi connectivity issue in A Block', 'IT', 'High', 'The Wi-Fi connection in A Block has been very slow or completely down since last Thursday. This is affecting online assignments and research work.', 'Ananya Barik', 'student', '2025-03-13', 'In Progress', 'Our IT team is actively working on the issue. Expected resolution within 48 hours.'),
('Canteen food quality needs improvement', 'Facilities', 'Low', 'The quality of food served in the main canteen has deteriorated significantly over the past month. Food is often cold and not fresh.', 'Sanjay Singh', 'student', '2025-03-05', 'Open', NULL),
('Lab computers require urgent maintenance', 'IT', 'High', 'Several computers in the Computer Lab are running very slowly. Some have outdated software that needs immediate updating for practical sessions.', 'Devansh Choudhury', 'student', '2025-03-09', 'In Progress', 'Maintenance has been scheduled for this weekend. All systems will be updated.'),
('Library does not have latest edition textbooks', 'Academic', 'Medium', 'The library does not have the latest editions of textbooks recommended in the new syllabus for Semester 4. Students are facing difficulty.', 'Rakesh Choudhury', 'student', '2025-03-06', 'Open', NULL),
('Attendance portal showing incorrect percentage', 'IT', 'High', 'The attendance portal is showing incorrect attendance percentages for students in the CSE department. This is causing unnecessary concern.', 'Mihir Das', 'student', '2025-03-18', 'Resolved', 'Data has been corrected. The issue was due to a sync error which has now been permanently fixed.'),
('Drinking water cooler not working in B Block', 'Facilities', 'High', 'The water cooler in A Block has been non-functional for 2 days. Students are facing difficulty getting drinking water.', 'Vinay Tripathy', 'student', '2025-03-17', 'Open', NULL),
('Exam hall seating arrangement not published', 'Admin', 'Medium', 'The seating arrangement for the upcoming end-semester examinations has not been published yet. Students are anxious about the same.', 'Payal Senapati', 'student', '2025-03-04', 'In Progress', 'Seating chart will be published 3 days before the examination commencement.'),
('Hostel room maintenance required', 'Facilities', 'Medium', 'The electrical fittings in hostel Block A Room 103 are faulty. There is a risk of short circuit. Immediate attention required.', 'Amrita Sahoo', 'student', '2025-03-21', 'Open', NULL),
('Sports equipment in poor condition', 'Facilities', 'Low', 'The sports equipment available in the sports room is in very poor condition. Badminton rackets, cricket bats need replacement urgently.', 'Vandana Parida', 'student', '2025-05-24', 'Resolved', 'New sports equipment has been procured and will be available from next week.'),
('Attendance portal showing incorrect percentage', 'IT', 'High', 'The attendance portal is showing incorrect attendance percentages for students in the CSE department. This is causing unnecessary concern.', 'Dr. Abhishek Panda', 'faculty', '2025-04-20', 'Resolved', 'Data has been corrected. The issue was due to a sync error which has now been permanently fixed.'),
